"""Team Task Tracker API - generated by Forge (AgentFlow)."""
from __future__ import annotations

from datetime import datetime, timezone
from itertools import count
from pathlib import Path
from typing import Literal, Optional

from fastapi import FastAPI, HTTPException, Response
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field

app = FastAPI(title="Team Task Tracker API", version="1.0.0")

Status = Literal["todo", "in_progress", "done"]
Priority = Literal["low", "medium", "high"]


class TaskIn(BaseModel):
    title: str = Field(min_length=1, max_length=120)
    description: str = ""
    priority: Priority = "medium"


class TaskPatch(BaseModel):
    title: Optional[str] = Field(default=None, min_length=1, max_length=120)
    description: Optional[str] = None
    priority: Optional[Priority] = None
    status: Optional[Status] = None


class Task(TaskIn):
    id: int
    status: Status = "todo"
    created_at: str


_db: dict[int, Task] = {}
_ids = count(1)


def _get_or_404(task_id: int) -> Task:
    if task_id not in _db:
        raise HTTPException(status_code=404, detail="Task not found")
    return _db[task_id]


@app.get("/", response_class=HTMLResponse, include_in_schema=False)
def ui() -> str:
    return (Path(__file__).parent / "static" / "index.html").read_text(encoding="utf-8")


@app.get("/health")
def health() -> dict:
    return {"status": "ok", "tasks": len(_db)}


@app.post("/tasks", response_model=Task, status_code=201)
def create_task(body: TaskIn) -> Task:
    task = Task(id=next(_ids), created_at=datetime.now(timezone.utc).isoformat(), **body.model_dump())
    _db[task.id] = task
    return task


@app.get("/tasks", response_model=list[Task])
def list_tasks(status: Optional[Status] = None) -> list[Task]:
    return [t for t in _db.values() if status is None or t.status == status]


@app.get("/tasks/{task_id}", response_model=Task)
def get_task(task_id: int) -> Task:
    return _get_or_404(task_id)


@app.patch("/tasks/{task_id}", response_model=Task)
def update_task(task_id: int, body: TaskPatch) -> Task:
    task = _get_or_404(task_id)
    updated = task.model_copy(update=body.model_dump(exclude_unset=True))
    _db[task_id] = updated
    return updated


@app.delete("/tasks/{task_id}", status_code=204)
def delete_task(task_id: int) -> Response:
    _get_or_404(task_id)
    del _db[task_id]
    return Response(status_code=204)
